#include <iostream>
#include <string>
class Course {
    std::string name_;
public:
    explicit Course(const std::string& value) { setName(value); }
    void setName(const std::string& value) { name_ = value.substr(0,25); }
    std::string name() const { return name_; }
};
int main() {
    std::string input; if (!std::getline(std::cin,input)) return 0;
    Course course(input);
    std::cout << course.name() << "\n" << course.name().size() << "\n";
}
